-- Ruby Kisses: Lápis de Boca Ultra Easy cor Deep Red
-- Preço de TESTE R$ 1,00 e ativo para venda (preço definitivo depois da reunião com o contador). Impostos em branco.
INSERT INTO "brands" ("id", "name", "active", "sortOrder", "createdAt", "updatedAt")
VALUES (gen_random_uuid(), 'Ruby Kisses', true, 13, now(), now())
ON CONFLICT ("name") DO NOTHING;

INSERT INTO "products" ("id", "sku", "name", "brandId", "description", "unit", "costCents", "taxRefBps", "priceCents",
                        "stockQty", "reservedQty", "active", "internalNotes", "createdAt", "updatedAt")
SELECT gen_random_uuid(), 'RK-LAPIS-LABIAL-DEEP-RED', 'Lápis Contorno Labial Ultra Easy Deep Red', b."id",
       'Lip Liner Ultra Easy • Cor Deep Red • Com apontador na tampa',
       'UN', 0, 0, 100, 0, 0, true,
       'PREÇO DE TESTE (R$ 1,00). Definir o preço real após a reunião com o contador.', now(), now()
  FROM "brands" b WHERE b."name" = 'Ruby Kisses'
ON CONFLICT ("sku") DO NOTHING;

INSERT INTO "stored_files" ("id", "area", "fileName", "mimeType", "sizeBytes", "data", "createdAt")
SELECT gen_random_uuid(), 'products', 'ruby-kisses-lapis-labial-deep-red.webp', 'image/webp', 13002, decode('', 'hex'), now()
WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName" = 'ruby-kisses-lapis-labial-deep-red.webp');
INSERT INTO "product_images" ("id", "productId", "fileName", "mimeType", "isPrimary", "sortOrder", "createdAt")
SELECT gen_random_uuid(), p."id", 'ruby-kisses-lapis-labial-deep-red.webp', 'image/webp', true, 0, now()
  FROM "products" p
 WHERE p."sku" = 'RK-LAPIS-LABIAL-DEEP-RED' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p."id");
